(arg) => {
            if (arg === undefined || arg.length === 0) {
                return undefined;
            }
            validateUrlPatterns(arg, '--blockedUrlPattern');
            return arg;
        }

(url) => {
            if (!url) {
                return;
            }
            let parsed;
            try {
                parsed = new URL(url);
            }
            catch {
                throw new Error(`Provided browserUrl ${url} is not valid URL.`);
            }
            // `new URL('localhost:9222')` parses with the scheme `localhost:`, but
            // the browser URL is fetched over HTTP to discover the WebSocket
            // endpoint, so only http: and https: can work.
            if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
                throw new Error(`Provided browserUrl ${url} must use http:// or https:// protocol.`);
            }
            return url;
        }

(value) => {
