(arg) => {
            if (arg === undefined) {
                return;
            }
            const parts = arg.split('x');
            const [width, height] = parts.map(Number);
            if (parts.length !== 2 ||
                !Number.isInteger(width) ||
                !Number.isInteger(height) ||
                width <= 0 ||
                height <= 0) {
                throw new Error('Invalid viewport. Expected format is `1280x720` with positive integer width and height.');
            }
            return {
                width,
                height,
            };
        }

(url) => {
            if (!url) {
                return;
            }
            try {
                const parsed = new URL(url);
                if (parsed.protocol !== 'ws:' && parsed.protocol !== 'wss:') {
                    throw new Error(`Provided wsEndpoint ${url} must use ws:// or wss:// protocol.`);
                }
                return url;
            }
            catch (error) {
                if (error.message.includes('ws://')) {
                    throw error;
                }
                throw new Error(`Provided wsEndpoint ${url} is not valid URL.`);
            }
        }

(val) => {
            if (!val) {
                return;
            }
            try {
                const parsed = typeof val === 'string' ? JSON.parse(val) : val;
                if (typeof parsed !== 'object' ||
                    parsed === null ||
                    Array.isArray(parsed)) {
                    throw new Error('Headers must be a JSON object');
                }
                const headers = {};
                for (const [key, value] of Object.entries(parsed)) {
                    if (typeof value !== 'string') {
                        throw new Error(`Header "${key}" must have a string value`);
                    }
                    headers[key] = value;
                }
                return headers;
            }
            catch (error) {
                throw new Error(`Invalid JSON for wsHeaders: ${error instanceof Error ? error.message : String(error)}`);
            }
        }
